    await enforceStored(`auth:${ctx.ip}`, settings.limits.authPer10Min, 6e5, TOO_MANY_FROM_HERE);
    const c = credentials(ctx, { needName: true });
    const existing = await db.get("SELECT * FROM users WHERE email = ?", c.email);
    if (existing && existing.opened_at) throw new HttpError(409, "EMAIL_IN_USE", "A YHOD workspace for this e-mail already exists. Enter its password to open it.");
